import type { Type } from './utils.js';

export interface TweetImage extends Type<'TweetImage'> {
    id: string,
    /** Alt text set on the media by the tweet author */
    altText?: string,
    availability: TweetMediaAvailability,
    /** Content warnings set by the user that uploaded this media */
    contentWarnings: {
        /** `adult_content` */
        nsfw: boolean,
        /** `graphic_violence` */
        sensitive: boolean,
        /** `other` */
        violence: boolean
    },
    /** Whether the image has the "Generated by Grok" disclaimer */
    isAiGenerated: boolean,
    /** Original width and height of the media */
    size: [number, number],
    /** Url of the image */
    url: string
}

export interface TweetVideo extends Omit<TweetImage, '__typename' | 'altText'>, Type<'TweetVideo'> {
    aspectRatio: [number, number],
    /** Duration in milliseconds */
    duration: number,
    /** Url for the video's thumbnail */
    thumbnailUrl: string,
    /** Variants for all video's qualities, from lowest to highest */
    variants: {
        bitrate?: number,
        contentType: string,
        url: string
    }[],
    /** Shorthand for the highest quality video variant */
    url: string
}

export interface TweetGif extends Omit<TweetVideo, '__typename' | 'duration'>, Type<'TweetGif'> {}
export type TweetMedia = TweetImage | TweetGif | TweetVideo;



/**
 * Data about an uploaded media file
 */
export interface TweetMediaData extends Type<'TweetMediaData'> {
    id: string,
    mediaKey: string,
    /** Size of the media in bytes */
    bytes: number,
    /** Mime type of the media, defaults to `video/mp4` for gifs, since Twitter stores gifs as mp4, but doesn't actually return any mime type on gif uploads specifically */
    contentType?: string,
    /** Amount of seconds left until the media id expires */
    expiresIn: number,
    /** Width and height of the media. Only available on images */
    size?: [number, number],
    /** Information about how Twitter handled the uploaded media */
    processing?: {
        state: TweetMediaState,
        progress?: number
    }
}

export interface _MediaUploadInit {
    media_id: number,
    media_id_string: string,
    expires_after_secs: number,
    media_key: string
}



/**
 * Availability status of a media
 * 
 * @default TweetMediaAvailability.Available
 */
export enum TweetMediaAvailability {
    Available = 'Available',
    /** Media was removed due to a DMCA demand */
    Copyright = 'Copyright',
    /** Media is unavailable in the region of the current IP address where the request was made */
    GeoBlocked = 'GeoBlocked',
    Other = 'Other'
}

export enum TweetMediaState {
    Success = 'Succeeded',
    Failure = 'Failed',
    Pending = 'Pending'
}
